export const STATUSES = Object.freeze(['PASS', 'FAIL', 'BLOCKED', 'NOT RUN']);
export const allChecks = () => MATRIX.flatMap((t) => t.checks.map((ch) => ({ ...ch, test: t.id })));
export const findTest = (id) => MATRIX.find((t) => t.id === id);
export const testIdOfCheck = (checkId) => checkId.split('.')[0];

/** FAIL beats BLOCKED beats NOT RUN; a test only passes when every check passed. */
export function aggregate(statuses) {
  if (statuses.length === 0) return 'NOT RUN';
  for (const s of ['FAIL', 'BLOCKED', 'NOT RUN']) if (statuses.includes(s)) return s;
  return 'PASS';
}

export function testStatus(test, results) {
  return aggregate(test.checks.map((ch) => results[ch.id]?.status ?? 'NOT RUN'));
}

/**
 * Required tests must all pass for ACCEPTED. Optional tests only count when they
 * fail, and local-only evidence (X7) never counts toward staging acceptance.
 */
export function overallVerdict(results) {
  const required = MATRIX.filter((t) => !t.optional && !t.localOnly);
  const rs = required.map((t) => testStatus(t, results));
  const optionalFailed = MATRIX.filter((t) => t.optional).some((t) => testStatus(t, results) === 'FAIL');
  if (rs.includes('FAIL') || optionalFailed) return 'REJECTED';
  return rs.every((s) => s === 'PASS') ? 'ACCEPTED' : 'INCOMPLETE';
}
